-- Verifica as funções reais e reverte todas as fixtures antes de concluir.
DO $test$
DECLARE
 u uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();token text:=encode(extensions.gen_random_bytes(32),'hex');token2 text:=encode(extensions.gen_random_bytes(32),'hex');
 a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();a2 uuid:=gen_random_uuid();
 g uuid:=gen_random_uuid();gr uuid:=gen_random_uuid();gw uuid:=gen_random_uuid();gn uuid:=gen_random_uuid();gn2 uuid:=gen_random_uuid();renewed uuid:=gen_random_uuid();
 ids uuid[];first_id uuid;middle_id uuid;last_id uuid;op uuid;gv integer;ev integer;old_gv integer;old_ev integer;
 today date:=mukirana_private.finance_today();r jsonb;q jsonb;meta jsonb;checks integer:=0;before_balance numeric;
BEGIN
 BEGIN
  INSERT INTO mukirana_private.users(id,email) VALUES(u,'occurrences-check-'||u||'@example.invalid'),(u2,'occurrences-check-'||u2||'@example.invalid');
  INSERT INTO mukirana_private.sessions(token_hash,user_id,expires_at) VALUES(encode(extensions.digest(token,'sha256'),'hex'),u,clock_timestamp()+interval '1 hour'),(encode(extensions.digest(token2,'sha256'),'hex'),u2,clock_timestamp()+interval '1 hour');
  r:=public.mukirana_accounts_save(token,a,0,'Banco','consumption',null,false);ASSERT r->>'status'='saved';
  r:=public.mukirana_accounts_save(token,b,0,'Reserva','investment',null,false);ASSERT r->>'status'='saved';
  r:=public.mukirana_accounts_save(token2,a2,0,'Outra pessoa','consumption',null,false);ASSERT r->>'status'='saved';
  r:=public.mukirana_categories_save(token,c,0,'Moradia',null);ASSERT r->>'status'='saved';
  r:=public.mukirana_categories_save(token2,c2,0,'Privada',null);ASSERT r->>'status'='saved';
  r:=public.mukirana_occurrences_preview(token,'installment',10000,'2027-01-31','monthly',3,null,null);
  ASSERT r->>'status'='ok' AND r->'preview'->>'count'='3' AND r->'preview'->>'totalCents'='10000' AND r->'preview'->>'firstAmountCents'='3334' AND r->'preview'->>'regularAmountCents'='3333','exact preview remainder';checks:=checks+1;
  ASSERT r->'preview'->'samples'->1->>'date'='2027-02-28' AND r->'preview'->'samples'->2->>'date'='2027-03-31','monthly original anchor';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'installment',100,'2024-02-29','yearly',5,null,null);
  ASSERT r->'preview'->'samples'->1->>'date'='2025-02-28' AND r->'preview'->'samples'->4->>'date'='2028-02-29','leap year anchor';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'installment',100,'2027-01-01','fortnightly',4,null,null);
  ASSERT r->'preview'->'samples'->1->>'date'='2027-01-16' AND r->'preview'->'samples'->2->>'date'='2027-01-31' AND r->'preview'->'samples'->3->>'date'='2027-02-15','fortnight is 15 days';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'recurring',500,'2027-01-15','monthly',null,3,null);
  ASSERT r->'preview'->>'count'='3' AND r->'preview'->>'lastDate'='2027-03-15' AND r->'preview'->>'totalCents'='1500','exclusive monthly duration';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'recurring',500,'2027-01-31','monthly',null,1,null);
  ASSERT r->'preview'->>'count'='1' AND r->'preview'->>'lastDate'='2027-01-31','exclusive clamped month boundary';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'recurring',500,'2027-01-15','weekly',null,1,null);
  ASSERT r->'preview'->>'count'='5' AND r->'preview'->>'lastDate'='2027-02-12','weekly bounded by months';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'recurring',500,'2027-01-15','yearly',null,1,null);
  ASSERT r->'preview'->>'count'='1','long frequency finite duration';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'installment',2,today,'monthly',3,null,null);ASSERT r->>'status'='invalid_request','no zero installments';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'installment',100,today,'monthly',1001,null,null);ASSERT r->>'status'='invalid_request','bounded quantity';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'recurring',100,today,'weekly',null,1200,null);ASSERT r->>'status'='too_many_occurrences','bounded generated count';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'recurring',100,today,'monthly',null,0,null);ASSERT r->>'status'='invalid_request','finite positive duration';checks:=checks+1;
  r:=public.mukirana_occurrences_create(token,g,'expense','  Compra  parcelada ',10000,'2027-01-31','monthly','installment',3,null,a,c,'variable',null,null);
  ASSERT r->>'status'='saved' AND r->'group'->>'totalCents'='10000' AND r->'group'->>'count'='3' AND r->'entry'->>'modality'='installment','creation real complete entries';checks:=checks+1;
  SELECT array_agg(id ORDER BY occurrence_index) INTO ids FROM mukirana_private.transactions WHERE user_id=u AND group_id=g;first_id:=ids[1];middle_id:=ids[2];last_id:=ids[3];
  ASSERT cardinality(ids)=3 AND (SELECT count(distinct id)=3 FROM mukirana_private.transactions WHERE group_id=g),'independent stable IDs';checks:=checks+1;
  ASSERT mukirana_private.account_position(u,a,today)=0 AND mukirana_private.account_position(u,a,'2027-03-31')=-10000,'future only projected';checks:=checks+1;
  r:=public.mukirana_occurrences_create(token,g,'expense','Compra parcelada',10000,'2027-01-31','monthly','installment',3,null,a,c,'variable',null,null);
  ASSERT r->>'status'='saved' AND r->'entry'->>'id'=first_id::text AND (SELECT count(*)=3 FROM mukirana_private.transactions WHERE group_id=g),'idempotent create no duplicate';checks:=checks+1;
  r:=public.mukirana_occurrences_create(token,g,'expense','Compra alterada',10000,'2027-01-31','monthly','installment',3,null,a,c,'variable',null,null);ASSERT r->>'status'='conflict','same ID different creation';checks:=checks+1;
  r:=public.mukirana_transactions_list(token,null,null,null,null,null,null,'',null,null,50);ASSERT r->'summary'->>'count'='0','legacy API remains single only';checks:=checks+1;
  r:=public.mukirana_transactions_list_series(token,null,null,null,null,null,null,'',null,null,2);
  ASSERT r->'summary'->>'count'='3' AND r->'summary'->>'expenseCents'='10000' AND jsonb_array_length(r->'entries')=2 AND (r->>'hasMore')::boolean AND jsonb_array_length(r->'groups')=1,'new listing group metadata and complete totals';checks:=checks+1;
  r:=public.mukirana_occurrences_get(token,middle_id,null);
  ASSERT r->>'status'='ok' AND r->'scopeCounts'->>'all'='3' AND r->'scopeCounts'->>'following'='2' AND r->'scopeCounts'->>'preceding'='2','scope counts independent of visible period';checks:=checks+1;
  gv:=(r->'group'->>'version')::integer;ev:=(r->'entry'->>'version')::integer;op:=gen_random_uuid();old_gv:=gv;old_ev:=ev;
  r:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,op,'save','one','{"amountCents":4000}'::jsonb);
  ASSERT r->>'status'='saved' AND r->>'affectedCount'='1' AND r->'group'->>'totalCents'='10667' AND (SELECT amount_cents=3334 FROM mukirana_private.transactions WHERE id=first_id) AND (SELECT amount_cents=3333 FROM mukirana_private.transactions WHERE id=last_id),'individual edit no redistribution';checks:=checks+1;
  gv:=(r->'group'->>'version')::integer;ev:=(r->'entry'->>'version')::integer;
  q:=public.mukirana_occurrences_change(token,g,old_gv,middle_id,old_ev,op,'save','one','{"amountCents":4000}'::jsonb);
  ASSERT q->>'status'='saved' AND q->'group'->>'version'=gv::text AND q->'entry'->>'version'=ev::text,'idempotent batch mutation receipt';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,old_gv,middle_id,old_ev,op,'save','one','{"amountCents":4500}'::jsonb);ASSERT q->>'status'='conflict','operation ID cannot change payload';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,old_gv,middle_id,ev,gen_random_uuid(),'save','all','{"description":"Stale"}'::jsonb);ASSERT q->>'status'='conflict','group stale version';checks:=checks+1;
  r:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','following','{"description":"Próximas"}'::jsonb);
  ASSERT r->>'status'='saved' AND r->>'affectedCount'='2' AND (SELECT description='Compra parcelada' FROM mukirana_private.transactions WHERE id=first_id) AND (SELECT description='Próximas' FROM mukirana_private.transactions WHERE id=last_id),'following changes only supplied fields';checks:=checks+1;
  gv:=(r->'group'->>'version')::integer;ev:=(r->'entry'->>'version')::integer;
  r:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','all','{"amountCents":3000,"date":"2028-01-31"}'::jsonb);
  ASSERT r->>'status'='saved' AND r->'group'->>'totalCents'='9000' AND (SELECT occurred_on='2027-12-31'::date FROM mukirana_private.transactions WHERE id=first_id) AND (SELECT occurred_on='2028-02-29'::date FROM mukirana_private.transactions WHERE id=last_id),'all amount per occurrence and anchored relative dates';checks:=checks+1;
  gv:=(r->'group'->>'version')::integer;ev:=(r->'entry'->>'version')::integer;
  q:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','all',jsonb_build_object('accountId',a2));ASSERT q->>'status'='invalid_account' AND (SELECT sum(amount_cents)=9000 FROM mukirana_private.transactions WHERE group_id=g),'foreign account all unchanged';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','all',jsonb_build_object('categoryId',c2));ASSERT q->>'status'='invalid_category','foreign category rejected';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','all','{"amountCents":1.5}'::jsonb);ASSERT q->>'status'='invalid_request','decimal cents rejected';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','all','{"date":null}'::jsonb);ASSERT q->>'status'='invalid_request','null date rejected';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','all','{"user_id":"attacker"}'::jsonb);ASSERT q->>'status'='invalid_request','patch whitelist';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,gen_random_uuid(),'save','all','{"date":"0001-01-01"}'::jsonb);
  ASSERT q->>'status'='invalid_request' AND (SELECT version=gv FROM mukirana_private.transaction_groups WHERE id=g) AND (SELECT occurred_on='2028-01-31'::date FROM mukirana_private.transactions WHERE id=middle_id),'invalid shifted dates rollback every row';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token2,g,gv,middle_id,ev,gen_random_uuid(),'delete','all','{}');ASSERT q->>'status'='not_found','foreign group mutation';checks:=checks+1;
  q:=public.mukirana_occurrences_get(token2,middle_id,null);ASSERT q->>'status'='not_found','foreign occurrence details';checks:=checks+1;
  op:=gen_random_uuid();old_gv:=gv;old_ev:=ev;
  r:=public.mukirana_occurrences_change(token,g,gv,middle_id,ev,op,'delete','preceding','{}');
  ASSERT r->>'status'='deleted' AND r->>'affectedCount'='2' AND r->'group'->>'count'='1' AND (SELECT occurrence_index=3 FROM mukirana_private.transactions WHERE id=last_id),'delete through selected preserves remaining index';checks:=checks+1;
  q:=public.mukirana_occurrences_change(token,g,old_gv,middle_id,old_ev,op,'delete','preceding','{}');ASSERT q->>'status'='deleted' AND q->'group'->>'count'='1','idempotent delete of absent selected row';checks:=checks+1;
  gv:=(r->'group'->>'version')::integer;SELECT version INTO ev FROM mukirana_private.transactions WHERE id=last_id;
  r:=public.mukirana_occurrences_change(token,g,gv,last_id,ev,gen_random_uuid(),'delete','one','{}');ASSERT r->>'status'='deleted' AND r->'group'->>'count'='0' AND r->'group'->>'totalCents'='0' AND NOT EXISTS(SELECT 1 FROM mukirana_private.transactions WHERE group_id=g),'single deletion leaves empty logical group no balance';checks:=checks+1;
  r:=public.mukirana_occurrences_create(token,gw,'income','Semanal',900,today-21,'weekly','installment',4,null,a,c,'fixed',null,null);ASSERT r->>'status'='saved';
  ASSERT mukirana_private.account_position(u,a,today)=900,'income installments current balance once';checks:=checks+1;
  SELECT id,version INTO middle_id,ev FROM mukirana_private.transactions WHERE group_id=gw AND occurrence_index=2;gv:=(r->'group'->>'version')::integer;
  r:=public.mukirana_occurrences_change(token,gw,gv,middle_id,ev,gen_random_uuid(),'delete','following','{}');ASSERT r->>'status'='deleted' AND r->'group'->>'count'='1' AND r->'group'->>'totalCents'='225','following deletion';checks:=checks+1;
  SELECT id,version INTO first_id,ev FROM mukirana_private.transactions WHERE group_id=gw;gv:=(r->'group'->>'version')::integer;
  r:=public.mukirana_occurrences_change(token,gw,gv,first_id,ev,gen_random_uuid(),'delete','all','{}');ASSERT r->>'status'='deleted' AND mukirana_private.account_position(u,a,today)=0,'delete all recalculates cash';checks:=checks+1;
  r:=public.mukirana_occurrences_create(token,gr,'expense','Recorrente variável',500,'2027-01-15','weekly','recurring',null,1,a,c,'variable',null,null);
  ASSERT r->>'status'='saved' AND r->'group'->>'count'='5' AND (SELECT bool_and(classification='variable') FROM mukirana_private.transactions WHERE group_id=gr),'recurrence independent of fixed classification';checks:=checks+1;
  q:=public.mukirana_transactions_list_series(token,null,null,null,null,null,null,'',null,null,100);
  ASSERT jsonb_array_length(q->'renewals')=0,'no notification at creation';checks:=checks+1;
  -- Conjunto antigo isolado para simular a chegada da última data, sem mudar relógio/produção.
  INSERT INTO mukirana_private.transaction_groups(id,user_id,nature,modality,frequency,start_on,anchor_day,duration_months,planned_count,creation_hash,created_at)
   VALUES(gn,u,'expense','recurring','monthly','2026-01-31',31,1,1,'fixture',timestamp with time zone '2026-01-01 00:00:00+00');
  INSERT INTO mukirana_private.transactions(user_id,nature,description,amount_cents,occurred_on,account_id,category_id,classification,modality,group_id,occurrence_index)
   VALUES(u,'expense','Renovar mensal',500,'2026-01-31',a,c,'variable','recurring',gn,1);
  q:=public.mukirana_transactions_list_series(token,'2099-01-01','2099-01-31',null,null,null,null,'',null,null,50);
  ASSERT jsonb_array_length(q->'entries')=0 AND jsonb_array_length(q->'renewals')=1 AND q->'renewals'->0->'group'->>'id'=gn::text,'renewal notice independent of period';checks:=checks+1;
  meta:=q->'renewals'->0->'group';gv:=(meta->>'version')::integer;
  ASSERT meta->>'nextDate'='2026-02-28' AND (meta->>'canRenew')::boolean,'renewal next anchored date';checks:=checks+1;
  r:=public.mukirana_occurrences_preview(token,'recurring',700,'2026-02-28','monthly',null,3,gn);
  ASSERT r->'preview'->'samples'->1->>'date'='2026-03-31' AND r->'preview'->'samples'->2->>'date'='2026-04-30','renewal retains original day anchor across clamped start';checks:=checks+1;
  r:=public.mukirana_occurrences_create(token,renewed,'expense','Renovada',700,'2026-02-28','monthly','recurring',null,3,b,c,'fixed',gn,gv);
  ASSERT r->>'status'='saved' AND r->'group'->>'count'='3' AND r->'group'->>'anchorDay'='31' AND r->'group'->>'totalCents'='2100','renewal new configuration';checks:=checks+1;
  q:=public.mukirana_occurrences_create(token,renewed,'expense','Renovada',700,'2026-02-28','monthly','recurring',null,3,b,c,'fixed',gn,gv);
  ASSERT q->>'status'='saved' AND (SELECT count(*)=1 FROM mukirana_private.transaction_groups WHERE renewed_from_id=gn),'idempotent renewal';checks:=checks+1;
  q:=public.mukirana_occurrences_create(token,gen_random_uuid(),'expense','Outra',700,'2026-02-28','monthly','recurring',null,3,b,c,'fixed',gn,gv);ASSERT q->>'status'='already_renewed','duplicate renewal refused';checks:=checks+1;
  q:=public.mukirana_transactions_list_series(token,null,null,null,null,null,null,'',null,null,100);ASSERT jsonb_array_length(q->'renewals')=0,'renewed notice removed and new series not notified at creation';checks:=checks+1;
  INSERT INTO mukirana_private.transaction_groups(id,user_id,nature,modality,frequency,start_on,anchor_day,duration_months,planned_count,creation_hash,created_at)
   VALUES(gn2,u,'income','recurring','weekly',today-7,extract(day FROM today-7)::integer,1,1,'fixture2',clock_timestamp()-interval '10 days');
  INSERT INTO mukirana_private.transactions(user_id,nature,description,amount_cents,occurred_on,account_id,category_id,classification,modality,group_id,occurrence_index)
   VALUES(u,'income','Dispensar aviso',100,today-7,a,c,'fixed','recurring',gn2,1);
  SELECT version INTO gv FROM mukirana_private.transaction_groups WHERE id=gn2;
  r:=public.mukirana_occurrences_dismiss(token,gn2,gv);ASSERT r->>'status'='dismissed','dismiss internal notification';checks:=checks+1;
  q:=public.mukirana_transactions_list_series(token,null,null,null,null,null,null,'',null,null,100);ASSERT jsonb_array_length(q->'renewals')=0,'dismissed notice stays hidden';checks:=checks+1;
  r:=public.mukirana_occurrences_get(token,null,gn2);ASSERT (r->'group'->>'canRenew')::boolean,'manual renewal remains possible after dismiss';checks:=checks+1;
  SELECT version INTO gv FROM mukirana_private.transaction_groups WHERE id=gr;SELECT id,version INTO first_id,ev FROM mukirana_private.transactions WHERE group_id=gr AND occurrence_index=1;
  r:=public.mukirana_transactions_save(token,first_id,ev,'expense','Edição legada',600,'2027-01-15',a,c,'variable');ASSERT r->>'status'='saved';
  q:=public.mukirana_occurrences_change(token,gr,gv,first_id,ev+1,gen_random_uuid(),'delete','all','{}');ASSERT q->>'status'='conflict','legacy individual edit advances group version';checks:=checks+1;
  ASSERT NOT has_table_privilege('service_role','mukirana_private.transaction_groups','SELECT') AND (SELECT relrowsecurity FROM pg_class WHERE oid='mukirana_private.transaction_groups'::regclass),'private RLS group table';checks:=checks+1;
  ASSERT NOT has_function_privilege('anon','public.mukirana_occurrences_change(text,uuid,integer,uuid,integer,uuid,text,text,jsonb)','EXECUTE')
   AND NOT has_function_privilege('authenticated','public.mukirana_occurrences_create(text,uuid,text,text,bigint,date,text,text,integer,integer,uuid,uuid,text,uuid,integer)','EXECUTE')
   AND has_function_privilege('service_role','public.mukirana_occurrences_get(text,uuid,uuid)','EXECUTE'),'RPC ACL';checks:=checks+1;
  r:=public.mukirana_occurrences_create(token,gen_random_uuid(),'expense','Privada',100,today,'monthly','installment',2,null,a2,c,'variable',null,null);ASSERT r->>'status'='invalid_account','foreign creation account';checks:=checks+1;
  r:=public.mukirana_occurrences_preview('', 'recurring',100,today,'monthly',null,1,null);ASSERT r->>'status'='invalid_session','empty session preview';checks:=checks+1;
  UPDATE mukirana_private.sessions SET revoked_at=clock_timestamp() WHERE user_id=u;
  r:=public.mukirana_occurrences_get(token,null,gr);ASSERT r->>'status'='invalid_session','revoked session read';checks:=checks+1;
  r:=public.mukirana_occurrences_change(token,gr,1,first_id,1,gen_random_uuid(),'delete','all','{}');ASSERT r->>'status'='invalid_session','revoked session mutation';checks:=checks+1;
  UPDATE mukirana_private.sessions SET created_at=clock_timestamp()-interval '2 hours',expires_at=clock_timestamp()-interval '1 hour' WHERE user_id=u2;
  r:=public.mukirana_occurrences_preview(token2,'recurring',100,today,'monthly',null,1,null);ASSERT r->>'status'='invalid_session','expired session';checks:=checks+1;
  RAISE SQLSTATE 'ZO001';
 EXCEPTION WHEN SQLSTATE 'ZO001' THEN NULL;END;
 ASSERT NOT EXISTS(SELECT 1 FROM mukirana_private.users WHERE id IN(u,u2)) AND NOT EXISTS(SELECT 1 FROM mukirana_private.transaction_groups WHERE user_id IN(u,u2)),'fixtures rolled back';checks:=checks+1;
 PERFORM set_config('mukirana.occurrence_checks',checks::text,true);
END;
$test$;
SELECT current_setting('mukirana.occurrence_checks')::integer AS passed,(SELECT count(*) FROM mukirana_private.users WHERE email LIKE 'occurrences-check-%@example.invalid') AS remaining_test_users;
